DECLARE @Orders TABLE
(
    ChannelName nvarchar(100) NOT NULL,
    ItemName nvarchar(200) NOT NULL,
    OrderDate date NOT NULL,
    OrderQty int NOT NULL,
    PRIMARY KEY (ChannelName, ItemName, OrderDate)
);

INSERT @Orders (ChannelName, ItemName, OrderDate, OrderQty)
SELECT item.ChannelName, item.ItemName,
       DATEADD(day, CONVERT(int, dayQty.[key]), CONVERT(date, '20260101')),
       CONVERT(int, dayQty.[value])
FROM OPENJSON(@Source)
WITH (ChannelName nvarchar(100) '$.c', ItemName nvarchar(200) '$.i', DailyQty nvarchar(max) '$.d' AS JSON) item
CROSS APPLY OPENJSON(item.DailyQty) dayQty;

UPDATE target
SET OrderQty = src.OrderQty
FROM dbo.PM_ForecastOrderActual target
INNER JOIN @Orders src ON src.ChannelName = target.ChannelName
    AND src.ItemName = target.ItemName AND src.OrderDate = target.OrderDate
WHERE target.CorpId = N'1000' AND target.OrderQty <> src.OrderQty;

INSERT dbo.PM_ForecastOrderActual (CorpId, ChannelName, ItemName, OrderDate, OrderQty)
SELECT N'1000', src.ChannelName, src.ItemName, src.OrderDate, src.OrderQty
FROM @Orders src
WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.PM_ForecastOrderActual target WITH (UPDLOCK, HOLDLOCK)
    WHERE target.CorpId = N'1000' AND target.ChannelName = src.ChannelName
      AND target.ItemName = src.ItemName AND target.OrderDate = src.OrderDate
);
COMMIT TRANSACTION;
